CREATE TABLE "User" ("id" TEXT NOT NULL PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "displayName" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "Session" ("id" TEXT NOT NULL PRIMARY KEY, "tokenHash" TEXT NOT NULL UNIQUE, "userId" TEXT NOT NULL, "expiresAt" DATETIME NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Source" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "url" TEXT NOT NULL UNIQUE, "tier" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "userId" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "Source_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Story" ("id" TEXT NOT NULL PRIMARY KEY, "canonicalUrl" TEXT NOT NULL, "title" TEXT NOT NULL, "publisher" TEXT NOT NULL, "publishedAt" DATETIME, "summary" TEXT, "entities" TEXT, "fingerprint" TEXT NOT NULL, "relevanceScore" REAL NOT NULL DEFAULT 0, "verificationScore" REAL NOT NULL DEFAULT 0, "status" TEXT NOT NULL DEFAULT 'INGESTED', "sourceId" TEXT NOT NULL, "userId" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "Story_sourceId_fkey" FOREIGN KEY ("sourceId") REFERENCES "Source" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "Story_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Claim" ("id" TEXT NOT NULL PRIMARY KEY, "statement" TEXT NOT NULL, "confidence" REAL NOT NULL, "sourceUrl" TEXT NOT NULL, "sourceName" TEXT NOT NULL, "isPrimary" BOOLEAN NOT NULL DEFAULT false, "storyId" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Claim_storyId_fkey" FOREIGN KEY ("storyId") REFERENCES "Story" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Draft" ("id" TEXT NOT NULL PRIMARY KEY, "storyId" TEXT NOT NULL, "userId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'DRAFT', "selectedVariant" INTEGER NOT NULL DEFAULT 0, "title" TEXT NOT NULL, "insightPacket" TEXT NOT NULL, "variants" TEXT NOT NULL, "body" TEXT NOT NULL, "hashtags" TEXT NOT NULL, "assetBrief" TEXT NOT NULL, "fallbackUsed" BOOLEAN NOT NULL DEFAULT false, "reviewedChecksum" TEXT, "approvedAt" DATETIME, "publishedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "Draft_storyId_fkey" FOREIGN KEY ("storyId") REFERENCES "Story" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "Draft_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "DraftRevision" ("id" TEXT NOT NULL PRIMARY KEY, "draftId" TEXT NOT NULL, "body" TEXT NOT NULL, "hashtags" TEXT NOT NULL, "action" TEXT NOT NULL, "checksum" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DraftRevision_draftId_fkey" FOREIGN KEY ("draftId") REFERENCES "Draft" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "StyleProfile" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "name" TEXT NOT NULL, "guide" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "StyleProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "ApprovedPostExample" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "body" TEXT NOT NULL, "metadata" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ApprovedPostExample_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Asset" ("id" TEXT NOT NULL PRIMARY KEY, "draftId" TEXT NOT NULL, "kind" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "storageKey" TEXT NOT NULL, "checksum" TEXT NOT NULL, "width" INTEGER NOT NULL DEFAULT 1200, "height" INTEGER NOT NULL DEFAULT 1200, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Asset_draftId_fkey" FOREIGN KEY ("draftId") REFERENCES "Draft" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "OAuthCredential" ("id" TEXT NOT NULL PRIMARY KEY, "provider" TEXT NOT NULL, "userId" TEXT NOT NULL, "memberUrn" TEXT NOT NULL, "memberName" TEXT, "encryptedAccessToken" TEXT NOT NULL, "expiresAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "OAuthCredential_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "PublishLog" ("id" TEXT NOT NULL PRIMARY KEY, "draftId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "contentChecksum" TEXT NOT NULL, "linkedInPostUrn" TEXT, "linkedInAssetUrn" TEXT, "payload" TEXT NOT NULL, "error" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PublishLog_draftId_fkey" FOREIGN KEY ("draftId") REFERENCES "Draft" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "AuditEvent" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "action" TEXT NOT NULL, "entityType" TEXT NOT NULL, "entityId" TEXT, "metadata" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditEvent_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Story_userId_canonicalUrl_key" ON "Story"("userId", "canonicalUrl");
CREATE UNIQUE INDEX "Story_userId_fingerprint_key" ON "Story"("userId", "fingerprint");
CREATE UNIQUE INDEX "OAuthCredential_userId_provider_key" ON "OAuthCredential"("userId", "provider");
CREATE INDEX "Session_userId_idx" ON "Session"("userId");
CREATE INDEX "Story_userId_status_idx" ON "Story"("userId", "status");
CREATE INDEX "Story_userId_relevanceScore_idx" ON "Story"("userId", "relevanceScore");
CREATE INDEX "Draft_userId_status_idx" ON "Draft"("userId", "status");
CREATE INDEX "AuditEvent_userId_createdAt_idx" ON "AuditEvent"("userId", "createdAt");
